const solid=(h,o=1)=>[{type:'SOLID',color:hex(h),opacity:o}];
const C={lime:'BBF246',dark:'192126',bg:'F7F8F9',white:'FFFFFF',muted:'8C9094'};
function T(chars,size,style,color,o={}){const t=figma.createText(); t.fontName={family:'Lato',style}; t.fontSize=size; t.characters=chars; t.fills=solid(color,o.op??1); t.name=o.name||chars.slice(0,30); return t;}
function F(name,fill,o={}){const f=figma.createFrame(); f.name=name; f.fills=fill?solid(fill):[]; if(o.w) f.resize(o.w,o.h||o.w); return f;}
const get=id=>figma.getNodeByIdAsync(id);
function sp(inst,map){const props=inst.componentProperties; const o={}; for(const [k,v] of Object.entries(map)){const key=Object.keys(props).find(p=>p.split('#')[0]===k); if(!key) throw new Error('prop '+k); o[key]=v;} inst.setProperties(o);}
function add(parent,node,x,y){parent.appendChild(node); node.x=x; node.y=y; return node;}
