const page=await figma.getNodeByIdAsync('24:2'); await figma.setCurrentPageAsync(page);
const get=id=>figma.getNodeByIdAsync(id);
const ID={ob:'33:154',hm:'33:179',ex:'33:334',wo:'34:401',an:'35:471'};
const fr={}; for(const k in ID) fr[k]=await get(ID[k]);
const go=(dest,trans)=>[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:trans,preserveScrollPosition:false}]}];
const dis={type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:0.2};
const push={type:'SLIDE_IN',direction:'LEFT',matchLayers:false,easing:{type:'EASE_IN_AND_OUT'},duration:0.3};
const pop={type:'SLIDE_OUT',direction:'RIGHT',matchLayers:false,easing:{type:'EASE_IN_AND_OUT'},duration:0.3};
const log=[];
async function link(node,dest,trans,label){try{await node.setReactionsAsync(go(dest,trans)); log.push('ok '+label);}catch(e){log.push('FAIL '+label+': '+e.message);}}
const tab=(f,n)=>f.findOne(x=>x.name==='Tab Bar').findOne(x=>x.name==='Tab/'+n);
await link(fr.ob.findOne(n=>n.name==='Get Started'),ID.hm,dis,'Get Started→Home');
await link(fr.hm.findOne(n=>n.name==='Lower Body Training'),ID.wo,push,'Lower Body→Workout');
