await link(tab(fr.hm,'Analytics'),ID.an,dis,'Home Analytics tab');
await link(tab(fr.ex,'Home'),ID.hm,dis,'Explore Home tab');
await link(tab(fr.ex,'Analytics'),ID.an,dis,'Explore Analytics tab');
await link(tab(fr.an,'Home'),ID.hm,dis,'Analytics Home tab');
await link(tab(fr.an,'Explore'),ID.ex,dis,'Analytics Explore tab');
await link(fr.wo.findOne(n=>n.name==='Nav Header').findOne(n=>n.name==='Back'),ID.hm,pop,'Workout back');
page.flowStartingPoints=[{nodeId:ID.ob,name:'Fitness App'}];
for(const k in fr){fr[k].overflowDirection = fr[k].height>844?'VERTICAL':'NONE';}
return log;

const page=await figma.getNodeByIdAsync('24:2');
const out=page.children.map(c=>`${c.id} ${c.name} ${Math.round(c.width)}x${Math.round(c.height)} @${c.x},${c.y}`);
const r=page.findAll(n=>n.reactions&&n.reactions.length>0).map(n=>`${n.name} -> ${n.reactions[0].actions[0].destinationId}`);
return {out,r,flows:page.flowStartingPoints};
